{
  render: args => {
    const [value, setValue] = useState<ResizeScale>('md');
    return <div>
        <div style={{
        marginBottom: '16px'
      }}>
          <p>
            현재 선택된 크기: <strong>{value}</strong>
          </p>
        </div>
        <Resize {...args} value={value} onChange={scale => {
        setValue(scale);
        args.onChange?.(scale);
      }} />
      </div>;
  },
  args: {
    buttonText: '화면크기',
    resetText: '초기화'
  },
  parameters: {
    docs: {
      description: {
        story: '제어 상태의 Resize 컴포넌트입니다.'
      }
    }
  }
}

